import React, { useState } from "react";
import { useAuth } from "../context/AuthContext";
import { login, register } from "../services/api";

export default function AuthPage() {
  const { signIn } = useAuth();
  const [tab, setTab] = useState("login");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");

  const [loginForm, setLoginForm] = useState({ username: "", password: "" });
  const [regForm, setRegForm] = useState({ username: "", password: "", fullName: "" });

  const handleLogin = async (e) => {
    e.preventDefault();
    if (!loginForm.username || !loginForm.password) { setError("Fill in all fields"); return; }
    setLoading(true); setError("");
    try {
      const { data } = await login(loginForm.username, loginForm.password);
      signIn(data.token, data.username);
    } catch (err) {
      setError(err.response?.data?.error || "Invalid credentials");
    } finally { setLoading(false); }
  };

  const handleRegister = async (e) => {
    e.preventDefault();
    if (!regForm.fullName || !regForm.username || !regForm.password) { setError("Fill in all fields"); return; }
    setLoading(true); setError(""); setSuccess("");
    try {
      await register(regForm.username, regForm.password, regForm.fullName);
      setSuccess("Account created! Sign in now.");
      setLoginForm({ username: regForm.username, password: "" });
      setTab("login");
    } catch (err) {
      setError(err.response?.data || err.response?.data?.error || "Registration failed");
    } finally { setLoading(false); }
  };

  return (
    <div className="min-h-screen bg-crisp-bg flex items-center justify-center p-4 relative overflow-hidden">
      {/* Background glow orbs */}
      <div className="absolute top-[-200px] left-[-200px] w-[600px] h-[600px] rounded-full
        bg-crisp-accent/5 blur-3xl pointer-events-none" />
      <div className="absolute bottom-[-150px] right-[-150px] w-[500px] h-[500px] rounded-full
        bg-crisp-teal/5 blur-3xl pointer-events-none" />

      <div className="w-full max-w-md animate-slideUp">
        {/* Logo */}
        <div className="flex items-center gap-3 mb-8">
          <div className="w-10 h-10 bg-crisp-accent rounded-xl flex items-center justify-center
            font-mono font-bold text-white text-lg shadow-lg shadow-crisp-accent/30">C</div>
          <span className="font-display font-bold text-2xl text-crisp-text tracking-tight">Crisp</span>
          <span className="ml-auto text-xs text-crisp-muted font-mono bg-crisp-card px-2 py-1 rounded-lg border border-crisp-border">
            v1.0
          </span>
        </div>

        <div className="bg-crisp-surface border border-crisp-border rounded-2xl p-8 shadow-2xl">
          {/* Tabs */}
          <div className="flex bg-crisp-bg rounded-xl p-1 mb-7 border border-crisp-border">
            {["login", "register"].map((t) => (
              <button
                key={t}
                onClick={() => { setTab(t); setError(""); setSuccess(""); }}
                className={`flex-1 py-2 rounded-lg font-display font-semibold text-sm transition-all duration-200
                  ${tab === t ? "bg-crisp-accent text-white shadow-sm" : "text-crisp-muted hover:text-crisp-sub"}`}
              >
                {t === "login" ? "Sign In" : "Register"}
              </button>
            ))}
          </div>

          {/* Alerts */}
          {error && (
            <div className="mb-5 px-4 py-3 bg-red-500/10 border border-red-500/20 rounded-xl
              text-red-300 text-sm font-body animate-fadeIn">
              {error}
            </div>
          )}
          {success && (
            <div className="mb-5 px-4 py-3 bg-emerald-500/10 border border-emerald-500/20 rounded-xl
              text-emerald-300 text-sm font-body animate-fadeIn">
              {success}
            </div>
          )}

          {/* Login Form */}
          {tab === "login" && (
            <form onSubmit={handleLogin} className="space-y-4">
              <Field label="Username">
                <input
                  className="input-field"
                  placeholder="your_username"
                  autoComplete="off"
                  value={loginForm.username}
                  onChange={(e) => setLoginForm({ ...loginForm, username: e.target.value })}
                />
              </Field>
              <Field label="Password">
                <input
                  className="input-field"
                  type="password"
                  placeholder="••••••••"
                  value={loginForm.password}
                  onChange={(e) => setLoginForm({ ...loginForm, password: e.target.value })}
                />
              </Field>
              <button type="submit" disabled={loading} className="btn-primary w-full mt-2">
                {loading ? <Spinner /> : "Sign In"}
              </button>
            </form>
          )}

          {/* Register Form */}
          {tab === "register" && (
            <form onSubmit={handleRegister} className="space-y-4">
              <Field label="Full Name">
                <input
                  className="input-field"
                  placeholder="Alex Johnson"
                  value={regForm.fullName}
                  onChange={(e) => setRegForm({ ...regForm, fullName: e.target.value })}
                />
              </Field>
              <Field label="Username">
                <input
                  className="input-field"
                  placeholder="alex_j"
                  autoComplete="off"
                  value={regForm.username}
                  onChange={(e) => setRegForm({ ...regForm, username: e.target.value })}
                />
              </Field>
              <Field label="Password">
                <input
                  className="input-field"
                  type="password"
                  placeholder="••••••••"
                  value={regForm.password}
                  onChange={(e) => setRegForm({ ...regForm, password: e.target.value })}
                />
              </Field>
              <button type="submit" disabled={loading} className="btn-primary w-full mt-2">
                {loading ? <Spinner /> : "Create Account"}
              </button>
            </form>
          )}
        </div>

        <p className="text-center text-crisp-muted text-xs mt-6 font-body">
          Real-time chat powered by Spring Boot + WebSocket
        </p>
      </div>
    </div>
  );
}

function Field({ label, children }) {
  return (
    <div>
      <label className="block text-xs font-display font-semibold text-crisp-muted uppercase
        tracking-widest mb-2">
        {label}
      </label>
      {children}
    </div>
  );
}

function Spinner() {
  return (
    <span className="flex items-center justify-center gap-2">
      <svg className="animate-spin w-4 h-4" viewBox="0 0 24 24" fill="none">
        <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"/>
        <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8v4a4 4 0 00-4 4H4z"/>
      </svg>
      Loading...
    </span>
  );
}
